type Portal = "teacher" | "student";
type Page = "overview" | "students" | "attendance" | "complaints" | "notes" | "classroom" | "alerts" | "notifications" | "profile";
type ComplaintStatus = "Submitted" | "Acknowledged" | "In progress" | "Resolved" | "Closed";
type Complaint = { id: string; title: string; category: string; location: string; student: string; time: string; status: ComplaintStatus; description: string };
type NoteRecord = { id: string; subject: string; topic: string; by: string; date: string; type: string; color: string; pages: string; fileUrl?: string | null; content?: string | null; classId?: string };
type StudentSubject = { classId: string; subjectId: string; teacherName: string; teacherEmail: string | null };
type AttendanceRecord = { id: number; classId: string; subject: string; attendanceDate: string; markedAt: number; status: "present" | "absent"; reviewStatus: "pending" | "approved" | "rejected"; confidence: number | null; evidenceUrl?: string | null };
type TeacherAttendanceRecord = AttendanceRecord & { studentId: number; studentName: string; rollNumber: string };
type StudentSubjectRow = typeof subjects[number] & { teacherName?: string };

